WITH lines AS (SELECT id, customer_id, created_at, code FROM carts LATERAL VIEW OUTER EXPLODE(coupon_codes) t AS code) SELECT customer_id, SORT_ARRAY(COLLECT_SET(code)) AS code_list, COUNT(DISTINCT id) AS distinct_ids, COUNT(*) FILTER (WHERE code = 'WELCOME5') AS welcome5_rows, COUNT(*) AS num_rows, (UNIX_TIMESTAMP(MAX(created_at)) - UNIX_TIMESTAMP(MIN(created_at))) / 60 AS duration_min FROM lines GROUP BY customer_id ORDER BY duration_min NULLS FIRST
